window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-08d115f96eb5db47"]={"versions": [{"id": "FIG-08d115f96eb5db47", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für Port-Kommunikationsspezifikationen (ComSpec) im Persistenz-Kontext der AUTOSAR Adaptive Platform (TPS Manifest Specification). Das Diagramm modelliert die strukturellen Zusammenhänge zwischen bereitstellenden bzw. anfordernden Port-Prototypen, den zugehörigen PortComSpecs sowie den persistierten Datenelementen und deren Initialwerten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell definiert folgende Klassen, Attribute und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>AbstractProvidedPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Besitzt per Komposition über die Rolle <code>+providedComSpec</code> mit Kardinalität <code>0..*</code> Instanzen von <code>PPortComSpec</code>.</li>\n<li><code>PPortComSpec</code>: Abstrakte Basisklasse für bereitstellende Port-Kommunikationsspezifikationen; wird spezialisiert durch <code>PersistencyDataProvidedComSpec</code>.</li>\n<li><code>PersistencyDataProvidedComSpec</code>: Modelliert die bereitstellende Kommunikationsspezifikation für persistente Daten. Besitzt das Attribut <code>+ redundancy: PersistencyRedundancyEnum [0..1]</code>. Sie referenziert per gerichteter Assoziation über <code>+dataElement</code> mit Kardinalität <code>1</code> das zugehörige <code>PersistencyDataElement</code> und besitzt per Komposition über <code>+initValue</code> mit Kardinalität <code>0..1</code> eine <code>ValueSpecification</code>.</li>\n<li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Besitzt per Komposition über die Rolle <code>+requiredComSpec</code> mit Kardinalität <code>0..*</code> Instanzen von <code>RPortComSpec</code>.</li>\n<li><code>RPortComSpec</code>: Abstrakte Basisklasse für anfordernde Port-Kommunikationsspezifikationen; wird spezialisiert durch <code>PersistencyDataRequiredComSpec</code>.</li>\n<li><code>PersistencyDataRequiredComSpec</code>: Modelliert die anfordernde Kommunikationsspezifikation für persistente Daten. Besitzt keine eigenen Attribute. Sie referenziert per gerichteter Assoziation über <code>+dataElement</code> mit Kardinalität <code>1</code> das zugehörige <code>PersistencyDataElement</code> und besitzt per Komposition über <code>+initValue</code> mit Kardinalität <code>0..1</code> eine <code>ValueSpecification</code>.</li>\n<li><code>PersistencyDataElement</code> (Spezialisierung von <code>AutosarDataPrototype</code>): Repräsentiert das persistente Datenelement im Interface. Besitzt das Attribut <code>+ updateStrategy: PersistencyElementLevelUpdateStrategyEnum</code>.</li>\n<li><code>ValueSpecification</code>: Spezifiziert Werte (z. B. Initialwerte) und deklariert das optionale Attribut <code>+ shortLabel: Identifier [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm stellt die Abbildung keine dynamischen Interaktionen oder Laufzeitsequenzen dar. Die Struktur definiert deklarativ die Konfiguration zur Entwurfs- und Manifest-Generierungszeit: Bei der Port-Instanziierung werden den Schnittstellen passende ComSpec-Instanzen (<code>PersistencyDataProvidedComSpec</code> bzw. <code>PersistencyDataRequiredComSpec</code>) zugeordnet, die jeweils genau ein <code>PersistencyDataElement</code> referenzieren und optional einen Default-/Initialwert (<code>ValueSpecification</code>) halten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Generatoren von AUTOSAR-Manifesten müssen sicherstellen:</p>\n<ul class=\"fig-list\">\n<li>Jeder <code>AbstractProvidedPortPrototype</code> kann null bis viele <code>PersistencyDataProvidedComSpec</code>-Elemente besitzen.</li>\n<li>Jeder <code>AbstractRequiredPortPrototype</code> kann null bis viele <code>PersistencyDataRequiredComSpec</code>-Elemente besitzen.</li>\n<li>Sowohl <code>PersistencyDataProvidedComSpec</code> als auch <code>PersistencyDataRequiredComSpec</code> müssen zwingend genau ein <code>PersistencyDataElement</code> referenzieren (<code>dataElement</code>-Multiplizität <code>1</code>).</li>\n<li>Die Bereitstellung von Initialwerten (<code>initValue</code>) ist auf beiden Seiten optional (<code>0..1</code>), jedoch als exklusive Komposition an die jeweilige ComSpec gebunden.</li>\n<li>Das Redundanzniveau kann auf Bereitstellerseite optional konfiguriert werden (<code>redundancy</code>), während die Aktualisierungsstrategie (<code>updateStrategy</code>) am <code>PersistencyDataElement</code> als Pflichtangabe geführt wird.</li>\n</ul>"}, {"id": "FIG-c11fd32ee4857996", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für Port-Kommunikationsspezifikationen (ComSpec) im Persistenz-Kontext der AUTOSAR Adaptive Platform (TPS Manifest Specification). Das Diagramm modelliert die strukturellen Zusammenhänge zwischen bereitstellenden bzw. anfordernden Port-Prototypen, den zugehörigen PortComSpecs sowie den persistierten Datenelementen und deren Initialwerten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell definiert folgende Klassen, Attribute und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>AbstractProvidedPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Besitzt per Komposition über die Rolle <code>+providedComSpec</code> mit Kardinalität <code>0..*</code> Instanzen von <code>PPortComSpec</code>.</li>\n<li><code>PPortComSpec</code>: Abstrakte Basisklasse für bereitstellende Port-Kommunikationsspezifikationen; wird spezialisiert durch <code>PersistencyDataProvidedComSpec</code>.</li>\n<li><code>PersistencyDataProvidedComSpec</code>: Modelliert die bereitstellende Kommunikationsspezifikation für persistente Daten. Besitzt keine Attribute. Sie referenziert per gerichteter Assoziation über <code>+dataElement</code> mit Kardinalität <code>1</code> das zugehörige <code>PersistencyDataElement</code> und besitzt per Komposition über <code>+initValue</code> mit Kardinalität <code>0..1</code> eine <code>ValueSpecification</code>.</li>\n<li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Besitzt per Komposition über die Rolle <code>+requiredComSpec</code> mit Kardinalität <code>0..*</code> Instanzen von <code>RPortComSpec</code>.</li>\n<li><code>RPortComSpec</code>: Abstrakte Basisklasse für anfordernde Port-Kommunikationsspezifikationen; wird spezialisiert durch <code>PersistencyDataRequiredComSpec</code>.</li>\n<li><code>PersistencyDataRequiredComSpec</code>: Modelliert die anfordernde Kommunikationsspezifikation für persistente Daten. Besitzt keine Attribute. Sie referenziert per gerichteter Assoziation über <code>+dataElement</code> mit Kardinalität <code>1</code> das zugehörige <code>PersistencyDataElement</code> und besitzt per Komposition über <code>+initValue</code> mit Kardinalität <code>0..1</code> eine <code>ValueSpecification</code>.</li>\n<li><code>PersistencyDataElement</code> (Spezialisierung von <code>AutosarDataPrototype</code>): Repräsentiert das persistente Datenelement im Interface. Besitzt das optionale Attribut <code>+ updateStrategy: PersistencyElementLevelUpdateStrategyEnum [0..1]</code>.</li>\n<li><code>ValueSpecification</code>: Spezifiziert Werte (z. B. Initialwerte) und deklariert das optionale Attribut <code>+ shortLabel: Identifier [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm stellt die Abbildung keine dynamischen Interaktionen oder Laufzeitsequenzen dar. Die Struktur definiert deklarativ die Konfiguration zur Entwurfs- und Manifest-Generierungszeit: Bei der Port-Instanziierung werden den Schnittstellen passende ComSpec-Instanzen (<code>PersistencyDataProvidedComSpec</code> bzw. <code>PersistencyDataRequiredComSpec</code>) zugeordnet, die jeweils genau ein <code>PersistencyDataElement</code> referenzieren und optional einen Default-/Initialwert (<code>ValueSpecification</code>) halten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Generatoren von AUTOSAR-Manifesten müssen sicherstellen:</p>\n<ul class=\"fig-list\">\n<li>Jeder <code>AbstractProvidedPortPrototype</code> kann null bis viele <code>PersistencyDataProvidedComSpec</code>-Elemente besitzen.</li>\n<li>Jeder <code>AbstractRequiredPortPrototype</code> kann null bis viele <code>PersistencyDataRequiredComSpec</code>-Elemente besitzen.</li>\n<li>Sowohl <code>PersistencyDataProvidedComSpec</code> als auch <code>PersistencyDataRequiredComSpec</code> müssen zwingend genau ein <code>PersistencyDataElement</code> referenzieren (<code>dataElement</code>-Multiplizität <code>1</code>).</li>\n<li>Die Bereitstellung von Initialwerten (<code>initValue</code>) ist auf beiden Seiten optional (<code>0..1</code>) und als Komposition an die jeweilige ComSpec gebunden.</li>\n<li>Das Attribut <code>updateStrategy</code> am <code>PersistencyDataElement</code> ist optional mit Multiplizität <code>[0..1]</code> ausgeprägt; <code>PersistencyDataProvidedComSpec</code> weist kein Redundanzattribut auf.</li>\n</ul>"}, {"id": "FIG-4226e77e19e50a95", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für Port-Kommunikationsspezifikationen (ComSpec) im Persistenz-Kontext der AUTOSAR Adaptive Platform (TPS Manifest Specification). Das Diagramm modelliert die strukturellen Zusammenhänge zwischen bereitstellenden bzw. anfordernden Port-Prototypen, den zugehörigen PortComSpecs sowie den persistierten Datenelementen und deren Initialwerten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell definiert folgende Klassen, Attribute und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>AbstractProvidedPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Besitzt per Komposition über die Rolle <code>+providedComSpec</code> mit Kardinalität <code>0..*</code> Instanzen von <code>PPortComSpec</code>.</li>\n<li><code>PPortComSpec</code>: Abstrakte Basisklasse für bereitstellende Port-Kommunikationsspezifikationen; wird spezialisiert durch <code>PersistencyDataProvidedComSpec</code>.</li>\n<li><code>PersistencyDataProvidedComSpec</code>: Modelliert die bereitstellende Kommunikationsspezifikation für persistente Daten. Besitzt keine Attribute. Sie referenziert per gerichteter Assoziation über <code>+dataElement</code> mit Kardinalität <code>1</code> das zugehörige <code>PersistencyDataElement</code> und besitzt per Komposition über <code>+initValue</code> mit Kardinalität <code>0..1</code> eine <code>ValueSpecification</code>.</li>\n<li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Besitzt per Komposition über die Rolle <code>+requiredComSpec</code> mit Kardinalität <code>0..*</code> Instanzen von <code>RPortComSpec</code>.</li>\n<li><code>RPortComSpec</code>: Abstrakte Basisklasse für anfordernde Port-Kommunikationsspezifikationen; wird spezialisiert durch <code>PersistencyDataRequiredComSpec</code>.</li>\n<li><code>PersistencyDataRequiredComSpec</code>: Modelliert die anfordernde Kommunikationsspezifikation für persistente Daten. Besitzt keine Attribute. Sie referenziert per gerichteter Assoziation über <code>+dataElement</code> mit Kardinalität <code>1</code> das zugehörige <code>PersistencyDataElement</code> und besitzt per Komposition über <code>+initValue</code> mit Kardinalität <code>0..1</code> eine <code>ValueSpecification</code>.</li>\n<li><code>PersistencyDataElement</code> (Spezialisierung von <code>AutosarDataPrototype</code>): Repräsentiert das persistente Datenelement im Interface. Besitzt das optionale Attribut <code>+ updateStrategy: PersistencyElementLevelUpdateStrategyEnum [0..1]</code>.</li>\n<li><code>ValueSpecification</code>: Spezifiziert Werte (z. B. Initialwerte) und deklariert das optionale Attribut <code>+ shortLabel: Identifier [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm stellt die Abbildung keine dynamischen Interaktionen oder Laufzeitsequenzen dar. Die Struktur definiert deklarativ die Konfiguration zur Entwurfs- und Manifest-Generierungszeit: Bei der Port-Instanziierung werden den Schnittstellen passende ComSpec-Instanzen (<code>PersistencyDataProvidedComSpec</code> bzw. <code>PersistencyDataRequiredComSpec</code>) zugeordnet, die jeweils genau ein <code>PersistencyDataElement</code> referenzieren und optional einen Default-/Initialwert (<code>ValueSpecification</code>) halten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Generatoren von AUTOSAR-Manifesten müssen sicherstellen:</p>\n<ul class=\"fig-list\">\n<li>Jeder <code>AbstractProvidedPortPrototype</code> kann null bis viele <code>PersistencyDataProvidedComSpec</code>-Elemente besitzen.</li>\n<li>Jeder <code>AbstractRequiredPortPrototype</code> kann null bis viele <code>PersistencyDataRequiredComSpec</code>-Elemente besitzen.</li>\n<li>Sowohl <code>PersistencyDataProvidedComSpec</code> als auch <code>PersistencyDataRequiredComSpec</code> müssen zwingend genau ein <code>PersistencyDataElement</code> referenzieren (<code>dataElement</code>-Multiplizität <code>1</code>).</li>\n<li>Die Bereitstellung von Initialwerten (<code>initValue</code>) ist auf beiden Seiten optional (<code>0..1</code>) und als Komposition an die jeweilige ComSpec gebunden.</li>\n<li>Das Attribut <code>updateStrategy</code> am <code>PersistencyDataElement</code> ist optional mit Multiplizität <code>[0..1]</code> ausgeprägt; <code>PersistencyDataProvidedComSpec</code> weist kein Redundanzattribut auf.</li>\n</ul>"}, {"id": "FIG-c62d87a8c822b08b", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für Port-Kommunikationsspezifikationen (ComSpec) im Persistenz-Kontext der AUTOSAR Adaptive Platform (TPS Manifest Specification). Das Diagramm modelliert die strukturellen Zusammenhänge zwischen bereitstellenden bzw. anfordernden Port-Prototypen, den zugehörigen PortComSpecs sowie den persistierten Datenelementen und deren Initialwerten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell definiert folgende Klassen, Attribute und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>AbstractProvidedPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Besitzt per Komposition über die Rolle <code>+providedComSpec</code> mit Kardinalität <code>0..*</code> Instanzen von <code>PPortComSpec</code>.</li>\n<li><code>PPortComSpec</code>: Abstrakte Basisklasse für bereitstellende Port-Kommunikationsspezifikationen; wird spezialisiert durch <code>PersistencyDataProvidedComSpec</code>.</li>\n<li><code>PersistencyDataProvidedComSpec</code>: Modelliert die bereitstellende Kommunikationsspezifikation für persistente Daten. Besitzt keine Attribute. Sie referenziert per gerichteter Assoziation über <code>+dataElement</code> mit Kardinalität <code>1</code> das zugehörige <code>PersistencyDataElement</code> und besitzt per Komposition über <code>+initValue</code> mit Kardinalität <code>0..1</code> eine <code>ValueSpecification</code>.</li>\n<li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Besitzt per Komposition über die Rolle <code>+requiredComSpec</code> mit Kardinalität <code>0..*</code> Instanzen von <code>RPortComSpec</code>.</li>\n<li><code>RPortComSpec</code>: Abstrakte Basisklasse für anfordernde Port-Kommunikationsspezifikationen; wird spezialisiert durch <code>PersistencyDataRequiredComSpec</code>.</li>\n<li><code>PersistencyDataRequiredComSpec</code>: Modelliert die anfordernde Kommunikationsspezifikation für persistente Daten. Besitzt keine Attribute. Sie referenziert per gerichteter Assoziation über <code>+dataElement</code> mit Kardinalität <code>1</code> das zugehörige <code>PersistencyDataElement</code> und besitzt per Komposition über <code>+initValue</code> mit Kardinalität <code>0..1</code> eine <code>ValueSpecification</code>.</li>\n<li><code>PersistencyDataElement</code> (Spezialisierung von <code>AutosarDataPrototype</code>): Repräsentiert das persistente Datenelement im Interface. Besitzt das optionale Attribut <code>+ updateStrategy: PersistencyElementLevelUpdateStrategyEnum [0..1]</code>.</li>\n<li><code>ValueSpecification</code>: Spezifiziert Werte (z. B. Initialwerte) und deklariert das optionale Attribut <code>+ shortLabel: Identifier [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm stellt die Abbildung keine dynamischen Interaktionen oder Laufzeitsequenzen dar. Die Struktur definiert deklarativ die Konfiguration zur Entwurfs- und Manifest-Generierungszeit: Bei der Port-Instanziierung werden den Schnittstellen passende ComSpec-Instanzen (<code>PersistencyDataProvidedComSpec</code> bzw. <code>PersistencyDataRequiredComSpec</code>) zugeordnet, die jeweils genau ein <code>PersistencyDataElement</code> referenzieren und optional einen Default-/Initialwert (<code>ValueSpecification</code>) halten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Generatoren von AUTOSAR-Manifesten müssen sicherstellen:</p>\n<ul class=\"fig-list\">\n<li>Jeder <code>AbstractProvidedPortPrototype</code> kann null bis viele <code>PersistencyDataProvidedComSpec</code>-Elemente besitzen.</li>\n<li>Jeder <code>AbstractRequiredPortPrototype</code> kann null bis viele <code>PersistencyDataRequiredComSpec</code>-Elemente besitzen.</li>\n<li>Sowohl <code>PersistencyDataProvidedComSpec</code> als auch <code>PersistencyDataRequiredComSpec</code> müssen zwingend genau ein <code>PersistencyDataElement</code> referenzieren (<code>dataElement</code>-Multiplizität <code>1</code>).</li>\n<li>Die Bereitstellung von Initialwerten (<code>initValue</code>) ist auf beiden Seiten optional (<code>0..1</code>) und als Komposition an die jeweilige ComSpec gebunden.</li>\n<li>Das Attribut <code>updateStrategy</code> am <code>PersistencyDataElement</code> ist optional mit Multiplizität <code>[0..1]</code> ausgeprägt; <code>PersistencyDataProvidedComSpec</code> weist kein Redundanzattribut auf.</li>\n</ul>"}, {"id": "FIG-2c70aa6302af29a4", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für anfordernde Port-Kommunikationsspezifikationen (ComSpec) im Persistenz-Kontext der AUTOSAR Adaptive Platform (TPS Manifest Specification). Das Diagramm fokussiert auf die Beziehung zwischen anfordernden Port-Prototypen, <code>PersistencyDataRequiredComSpec</code>, persistenten Schnittstellenelementen und deren Initialwerten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Besitzt per Komposition über die Rolle <code>+requiredComSpec</code> mit Kardinalität <code>0..*</code> Instanzen von <code>RPortComSpec</code>.</li>\n<li><code>RPortComSpec</code>: Abstrakte Basisklasse für anfordernde Port-Kommunikationsspezifikationen; wird spezialisiert durch <code>PersistencyDataRequiredComSpec</code>.</li>\n<li><code>PersistencyDataRequiredComSpec</code>: Modelliert die anfordernde Kommunikationsspezifikation für persistente Daten. Sie referenziert per gerichteter Assoziation über <code>+dataElement</code> mit Kardinalität <code>1</code> das zugehörige <code>PersistencyDataElement</code> und besitzt per Komposition über <code>+initValue</code> mit Kardinalität <code>0..1</code> eine <code>ValueSpecification</code>.</li>\n<li><code>PersistencyDataElement</code> (Spezialisierung von <code>AutosarDataPrototype</code> und <code>PersistencyInterfaceElement</code>): Repräsentiert das persistente Datenelement der Schnittstelle; besitzt keine Attribute im Diagramm.</li>\n<li><code>ValueSpecification</code>: Repräsentiert konfigurierte Initialwerte und besitzt das Attribut <code>+ shortLabel: Identifier [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm stellt die Abbildung keine dynamischen Interaktionen oder Laufzeitsequenzen dar. Die Struktur definiert deklarativ die Konfiguration zur Entwurfs- und Manifest-Generierungszeit: Bei der Port-Instanziierung werden den Schnittstellen passende ComSpec-Instanzen (<code>PersistencyDataProvidedComSpec</code> bzw. <code>PersistencyDataRequiredComSpec</code>) zugeordnet, die jeweils genau ein <code>PersistencyDataElement</code> referenzieren und optional einen Default-/Initialwert (<code>ValueSpecification</code>) halten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Generatoren von AUTOSAR-Manifesten müssen beachten:</p>\n<ul class=\"fig-list\">\n<li>Die Modellierung der Persistenz-ComSpecs ist auf anfordernde Schnittstellen (<code>PersistencyDataRequiredComSpec</code>) begrenzt; bereitstellende ComSpecs für Persistenzdaten sind im Metamodellausschnitt nicht mehr vorhanden.</li>\n<li>Jede <code>PersistencyDataRequiredComSpec</code> muss exakt ein <code>PersistencyDataElement</code> referenzieren (<code>dataElement 1</code>).</li>\n<li>Die Angabe von Initialwerten (<code>initValue</code>) an der <code>PersistencyDataRequiredComSpec</code> ist optional (<code>0..1</code>).</li>\n<li><code>PersistencyDataElement</code> fungiert als <code>PersistencyInterfaceElement</code>.</li>\n</ul>"}, {"id": "FIG-1a2732c4ad1e1a3d", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für anfordernde Port-Kommunikationsspezifikationen (ComSpec) im Persistenz-Kontext der AUTOSAR Adaptive Platform (TPS Manifest Specification). Das Diagramm fokussiert auf die Beziehung zwischen anfordernden Port-Prototypen, <code>PersistencyDataRequiredComSpec</code>, persistenten Schnittstellenelementen und deren Initialwerten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Besitzt per Komposition über die Rolle <code>+requiredComSpec</code> mit Kardinalität <code>0..*</code> Instanzen von <code>RPortComSpec</code>.</li>\n<li><code>RPortComSpec</code>: Abstrakte Basisklasse für anfordernde Port-Kommunikationsspezifikationen; wird spezialisiert durch <code>PersistencyDataRequiredComSpec</code>.</li>\n<li><code>PersistencyDataRequiredComSpec</code>: Modelliert die anfordernde Kommunikationsspezifikation für persistente Daten. Sie referenziert per gerichteter Assoziation über <code>+dataElement</code> mit Kardinalität <code>1</code> das zugehörige <code>PersistencyDataElement</code> und besitzt per Komposition über <code>+initValue</code> mit Kardinalität <code>0..1</code> eine <code>ValueSpecification</code>.</li>\n<li><code>PersistencyDataElement</code> (Spezialisierung von <code>AutosarDataPrototype</code> und <code>PersistencyInterfaceElement</code>): Repräsentiert das persistente Datenelement der Schnittstelle; besitzt keine Attribute im Diagramm.</li>\n<li><code>ValueSpecification</code>: Repräsentiert konfigurierte Initialwerte und besitzt das Attribut <code>+ shortLabel: Identifier [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm stellt die Abbildung keine dynamischen Interaktionen oder Laufzeitsequenzen dar. Die Struktur definiert deklarativ die Konfiguration zur Entwurfs- und Manifest-Generierungszeit: Bei der Port-Instanziierung werden den Schnittstellen passende ComSpec-Instanzen (<code>PersistencyDataProvidedComSpec</code> bzw. <code>PersistencyDataRequiredComSpec</code>) zugeordnet, die jeweils genau ein <code>PersistencyDataElement</code> referenzieren und optional einen Default-/Initialwert (<code>ValueSpecification</code>) halten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Generatoren von AUTOSAR-Manifesten müssen beachten:</p>\n<ul class=\"fig-list\">\n<li>Die Modellierung der Persistenz-ComSpecs ist auf anfordernde Schnittstellen (<code>PersistencyDataRequiredComSpec</code>) begrenzt; bereitstellende ComSpecs für Persistenzdaten sind im Metamodellausschnitt nicht mehr vorhanden.</li>\n<li>Jede <code>PersistencyDataRequiredComSpec</code> muss exakt ein <code>PersistencyDataElement</code> referenzieren (<code>dataElement 1</code>).</li>\n<li>Die Angabe von Initialwerten (<code>initValue</code>) an der <code>PersistencyDataRequiredComSpec</code> ist optional (<code>0..1</code>).</li>\n<li><code>PersistencyDataElement</code> fungiert als <code>PersistencyInterfaceElement</code>.</li>\n</ul>"}, {"id": "FIG-ca0ed6ec0cbf9114", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für anfordernde Port-Kommunikationsspezifikationen (ComSpec) im Persistenz-Kontext der AUTOSAR Adaptive Platform (TPS Manifest Specification). Das Diagramm fokussiert auf die Beziehung zwischen anfordernden Port-Prototypen, <code>PersistencyDataRequiredComSpec</code>, persistenten Schnittstellenelementen und deren Initialwerten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Besitzt per Komposition über die Rolle <code>+requiredComSpec</code> mit Kardinalität <code>0..*</code> Instanzen von <code>RPortComSpec</code>.</li>\n<li><code>RPortComSpec</code>: Abstrakte Basisklasse für anfordernde Port-Kommunikationsspezifikationen; wird spezialisiert durch <code>PersistencyDataRequiredComSpec</code>.</li>\n<li><code>PersistencyDataRequiredComSpec</code>: Modelliert die anfordernde Kommunikationsspezifikation für persistente Daten. Sie referenziert per gerichteter Assoziation über <code>+dataElement</code> mit Kardinalität <code>0..1</code> das zugehörige <code>PersistencyDataElement</code> und besitzt per Komposition über <code>+initValue</code> mit Kardinalität <code>0..1</code> eine <code>ValueSpecification</code>.</li>\n<li><code>PersistencyDataElement</code> (Spezialisierung von <code>AutosarDataPrototype</code> und <code>PersistencyInterfaceElement</code>): Repräsentiert das persistente Datenelement der Schnittstelle; besitzt keine Attribute im Diagramm.</li>\n<li><code>ValueSpecification</code>: Repräsentiert konfigurierte Initialwerte und besitzt das Attribut <code>+ shortLabel: Identifier [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm stellt die Abbildung keine dynamischen Interaktionen oder Laufzeitsequenzen dar. Die Struktur definiert deklarativ die Konfiguration zur Entwurfs- und Manifest-Generierungszeit: Bei der Port-Instanziierung werden den Schnittstellen passende ComSpec-Instanzen (<code>PersistencyDataProvidedComSpec</code> bzw. <code>PersistencyDataRequiredComSpec</code>) zugeordnet, die jeweils genau ein <code>PersistencyDataElement</code> referenzieren und optional einen Default-/Initialwert (<code>ValueSpecification</code>) halten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Generatoren von AUTOSAR-Manifesten müssen beachten:</p>\n<ul class=\"fig-list\">\n<li>Die Assoziation von <code>PersistencyDataRequiredComSpec</code> zum <code>PersistencyDataElement</code> ist optional mit Kardinalität <code>0..1</code> (<code>+dataElement 0..1</code>), sodass eine ComSpec auch ohne direkte Bindung an ein konkretes <code>PersistencyDataElement</code> existieren kann.</li>\n<li>Die Komposition <code>+initValue</code> zur <code>ValueSpecification</code> verbleibt optional (<code>0..1</code>).</li>\n<li><code>AbstractRequiredPortPrototype</code> bindet unverändert <code>0..*</code> Instanzen von <code>RPortComSpec</code> ein.</li>\n</ul>"}, {"id": "FIG-fecb9345a1146cca", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für anfordernde Port-Kommunikationsspezifikationen (ComSpec) im Persistenz-Kontext der AUTOSAR Adaptive Platform (TPS Manifest Specification). Das Diagramm fokussiert auf die Beziehung zwischen anfordernden Port-Prototypen, <code>PersistencyDataRequiredComSpec</code>, persistenten Schnittstellenelementen und deren Initialwerten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Besitzt per Komposition mit dem Stereotyp <code>«atpSplitable»</code> über die Rolle <code>+requiredComSpec</code> mit Kardinalität <code>0..*</code> Instanzen von <code>RPortComSpec</code>.</li>\n<li><code>RPortComSpec</code>: Abstrakte Basisklasse für anfordernde Port-Kommunikationsspezifikationen; wird spezialisiert durch <code>PersistencyDataRequiredComSpec</code>.</li>\n<li><code>PersistencyDataRequiredComSpec</code>: Modelliert die anfordernde Kommunikationsspezifikation für persistente Daten. Sie referenziert per gerichteter Assoziation über <code>+dataElement</code> mit Kardinalität <code>0..1</code> das zugehörige <code>PersistencyDataElement</code> und besitzt per Komposition über <code>+initValue</code> mit Kardinalität <code>0..1</code> eine <code>ValueSpecification</code>.</li>\n<li><code>PersistencyDataElement</code> (Spezialisierung von <code>AutosarDataPrototype</code> und <code>PersistencyInterfaceElement</code>): Repräsentiert das persistente Datenelement der Schnittstelle; besitzt keine Attribute im Diagramm.</li>\n<li><code>ValueSpecification</code>: Repräsentiert konfigurierte Initialwerte und besitzt das Attribut <code>+ shortLabel: Identifier [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm stellt die Abbildung keine dynamischen Interaktionen oder Laufzeitsequenzen dar. Die Struktur definiert deklarativ die Konfiguration zur Entwurfs- und Manifest-Generierungszeit: Bei der Port-Instanziierung werden den Schnittstellen passende ComSpec-Instanzen (<code>PersistencyDataProvidedComSpec</code> bzw. <code>PersistencyDataRequiredComSpec</code>) zugeordnet, die jeweils genau ein <code>PersistencyDataElement</code> referenzieren und optional einen Default-/Initialwert (<code>ValueSpecification</code>) halten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Generatoren von AUTOSAR-Manifesten müssen beachten:</p>\n<ul class=\"fig-list\">\n<li>Die Assoziation von <code>PersistencyDataRequiredComSpec</code> zum <code>PersistencyDataElement</code> ist optional mit Kardinalität <code>0..1</code> (<code>+dataElement 0..1</code>), sodass eine ComSpec auch ohne direkte Bindung an ein konkretes <code>PersistencyDataElement</code> existieren kann.</li>\n<li>Die Komposition <code>+initValue</code> zur <code>ValueSpecification</code> ist optional (<code>0..1</code>).</li>\n<li>Die Komposition <code>+requiredComSpec</code> von <code>AbstractRequiredPortPrototype</code> zu <code>RPortComSpec</code> trägt das Stereotyp <code>«atpSplitable»</code> und bindet <code>0..*</code> Instanzen ein, was ein Aufteilen über mehrere Manifest-Dateien (ARXML-Splitting) ermöglicht.</li>\n</ul>"}, {"id": "FIG-90c21340cfd404d8", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für anfordernde Port-Kommunikationsspezifikationen (ComSpec) im Persistenz-Kontext der AUTOSAR Adaptive Platform (TPS Manifest Specification). Das Diagramm fokussiert auf die Vererbungshierarchie ausgehend von <code>RPortComSpec</code> über die Zwischenklasse <code>AbstractPersistencyRequireComSpec</code> zu <code>PersistencyDataRequiredComSpec</code>, deren Zugriffskonfiguration (<code>PersistencyAccessEnum</code>), persistente Schnittstellenelemente sowie Initialwerte.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst folgende Klassen, Enumerationen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Besitzt per Komposition mit dem Stereotyp <code>«atpSplitable»</code> über die Rolle <code>+requiredComSpec</code> mit Kardinalität <code>0..*</code> Instanzen von <code>RPortComSpec</code>.</li>\n<li><code>RPortComSpec</code>: Abstrakte Basisklasse für anfordernde Port-Kommunikationsspezifikationen; wird generalisierend vererbt an <code>AbstractPersistencyRequireComSpec</code>.</li>\n<li><code>AbstractPersistencyRequireComSpec</code>: Abstrakte Basisklasse für persistenzspezifische anfordernde ComSpecs; besitzt das optionale Attribut <code>+ accessMode: PersistencyAccessEnum [0..1]</code>.</li>\n<li><code>PersistencyDataRequiredComSpec</code> (Spezialisierung von <code>AbstractPersistencyRequireComSpec</code>): Modelliert die anfordernde Kommunikationsspezifikation für persistente Daten. Sie referenziert per gerichteter Assoziation über <code>+dataElement</code> mit Kardinalität <code>0..1</code> das zugehörige <code>PersistencyDataElement</code> und besitzt per Komposition über <code>+initValue</code> mit Kardinalität <code>0..1</code> eine <code>ValueSpecification</code>.</li>\n<li><code>PersistencyDataElement</code> (Spezialisierung von <code>AutosarDataPrototype</code> und <code>PersistencyInterfaceElement</code>): Repräsentiert das persistente Datenelement der Schnittstelle; besitzt keine Attribute im Diagramm.</li>\n<li><code>ValueSpecification</code>: Repräsentiert konfigurierte Initialwerte und besitzt das Attribut <code>+ shortLabel: Identifier [0..1]</code>.</li>\n<li><code>«enumeration» PersistencyAccessEnum</code>: Definiert die Zugriffsmodi mit den Literalen <code>read</code>, <code>write</code> und <code>readWrite</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm stellt die Abbildung keine dynamischen Interaktionen oder Laufzeitsequenzen dar. Die Struktur definiert deklarativ die Konfiguration zur Entwurfs- und Manifest-Generierungszeit: Bei der Port-Instanziierung werden den Schnittstellen passende ComSpec-Instanzen (<code>PersistencyDataProvidedComSpec</code> bzw. <code>PersistencyDataRequiredComSpec</code>) zugeordnet, die jeweils genau ein <code>PersistencyDataElement</code> referenzieren und optional einen Default-/Initialwert (<code>ValueSpecification</code>) halten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Generatoren von AUTOSAR-Manifesten müssen beachten:</p>\n<ul class=\"fig-list\">\n<li>Der Zugriffsmodus kann auf Ebene von <code>AbstractPersistencyRequireComSpec</code> optional über <code>+ accessMode: PersistencyAccessEnum [0..1]</code> definiert werden; zulässige Werte sind <code>read</code>, <code>write</code> und <code>readWrite</code>.</li>\n<li>Die Assoziation von <code>PersistencyDataRequiredComSpec</code> zum <code>PersistencyDataElement</code> ist optional mit Kardinalität <code>0..1</code> (<code>+dataElement 0..1</code>), sodass eine ComSpec auch ohne direkte Bindung an ein konkretes <code>PersistencyDataElement</code> existieren kann.</li>\n<li>Die Komposition <code>+initValue</code> zur <code>ValueSpecification</code> ist optional (<code>0..1</code>).</li>\n<li>Die Komposition <code>+requiredComSpec</code> von <code>AbstractRequiredPortPrototype</code> zu <code>RPortComSpec</code> trägt das Stereotyp <code>«atpSplitable»</code> mit Kardinalität <code>0..*</code>.</li>\n</ul>"}, {"id": "FIG-381a8f592cbd83e0", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für anfordernde Port-Kommunikationsspezifikationen (ComSpec) im Persistenz-Kontext der AUTOSAR Adaptive Platform (TPS Manifest Specification). Das Diagramm fokussiert auf die Vererbungshierarchie ausgehend von <code>RPortComSpec</code> über die Zwischenklasse <code>AbstractPersistencyRequireComSpec</code> zu <code>PersistencyDataRequiredComSpec</code>, deren Zugriffskonfiguration (<code>PersistencyAccessEnum</code>), persistente Schnittstellenelemente sowie Initialwerte.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst folgende Klassen, Enumerationen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>AbstractRequiredPortPrototype</code> (Spezialisierung von <code>PortPrototype</code>): Besitzt per Komposition mit dem Stereotyp <code>«atpSplitable»</code> über die Rolle <code>+requiredComSpec</code> mit Kardinalität <code>0..*</code> Instanzen von <code>RPortComSpec</code>.</li>\n<li><code>RPortComSpec</code>: Abstrakte Basisklasse für anfordernde Port-Kommunikationsspezifikationen; wird generalisierend vererbt an <code>AbstractPersistencyRequireComSpec</code>.</li>\n<li><code>AbstractPersistencyRequireComSpec</code>: Abstrakte Basisklasse für persistenzspezifische anfordernde ComSpecs; besitzt das optionale Attribut <code>+ accessMode: PersistencyAccessEnum [0..1]</code>.</li>\n<li><code>PersistencyDataRequiredComSpec</code> (Spezialisierung von <code>AbstractPersistencyRequireComSpec</code>): Modelliert die anfordernde Kommunikationsspezifikation für persistente Daten. Sie referenziert per gerichteter Assoziation mit dem Stereotyp <code>«atpIdentityContributor»</code> über <code>+dataElement</code> mit Kardinalität <code>0..1</code> das zugehörige <code>PersistencyDataElement</code> und besitzt per Komposition über <code>+initValue</code> mit Kardinalität <code>0..1</code> eine <code>ValueSpecification</code>.</li>\n<li><code>PersistencyDataElement</code> (Spezialisierung von <code>AutosarDataPrototype</code> und <code>PersistencyInterfaceElement</code>): Repräsentiert das persistente Datenelement der Schnittstelle; besitzt keine Attribute im Diagramm.</li>\n<li><code>ValueSpecification</code>: Repräsentiert konfigurierte Initialwerte und besitzt das Attribut <code>+ shortLabel: Identifier [0..1]</code>.</li>\n<li><code>«enumeration» PersistencyAccessEnum</code>: Definiert die Zugriffsmodi mit den Literalen <code>read</code>, <code>write</code>, <code>readWrite</code> und <code>writeOnlyOnce</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm stellt die Abbildung keine dynamischen Interaktionen oder Laufzeitsequenzen dar. Die Struktur definiert deklarativ die Konfiguration zur Entwurfs- und Manifest-Generierungszeit: Bei der Port-Instanziierung werden den Schnittstellen passende ComSpec-Instanzen (<code>PersistencyDataProvidedComSpec</code> bzw. <code>PersistencyDataRequiredComSpec</code>) zugeordnet, die jeweils genau ein <code>PersistencyDataElement</code> referenzieren und optional einen Default-/Initialwert (<code>ValueSpecification</code>) halten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Generatoren von AUTOSAR-Manifesten müssen beachten:</p>\n<ul class=\"fig-list\">\n<li>Der Zugriffsmodus über <code>+ accessMode: PersistencyAccessEnum [0..1]</code> unterstützt die Literale <code>read</code>, <code>write</code>, <code>readWrite</code> sowie <code>writeOnlyOnce</code>.</li>\n<li>Die Assoziation <code>+dataElement</code> (<code>0..1</code>) zum <code>PersistencyDataElement</code> ist mit dem Stereotyp <code>«atpIdentityContributor»</code> gekennzeichnet und trägt somit zur Identitätsbildung der ComSpec bei.</li>\n<li>Die Komposition <code>+initValue</code> zur <code>ValueSpecification</code> ist optional (<code>0..1</code>).</li>\n<li>Die Komposition <code>+requiredComSpec</code> von <code>AbstractRequiredPortPrototype</code> zu <code>RPortComSpec</code> trägt das Stereotyp <code>«atpSplitable»</code> mit Kardinalität <code>0..*</code>.</li>\n</ul>"}], "trans": [{"from": "FIG-08d115f96eb5db47", "to": "FIG-c11fd32ee4857996", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Attribut <code>redundancy: PersistencyRedundancyEnum [0..1]</code> in Klasse <code>PersistencyDataProvidedComSpec</code> entfernt.</li>\n<li>Attribut <code>updateStrategy: PersistencyElementLevelUpdateStrategyEnum</code> in Klasse <code>PersistencyDataElement</code> um Multiplizität <code>[0..1]</code> ergänzt (<code>+ updateStrategy: PersistencyElementLevelUpdateStrategyEnum [0..1]</code>).</li>\n</ul>"}, {"from": "FIG-c11fd32ee4857996", "to": "FIG-4226e77e19e50a95", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4226e77e19e50a95", "to": "FIG-c62d87a8c822b08b", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c62d87a8c822b08b", "to": "FIG-2c70aa6302af29a4", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Klassen <code>AbstractProvidedPortPrototype</code>, <code>PPortComSpec</code> und <code>PersistencyDataProvidedComSpec</code> mitsamt ihren Assoziationen (<code>+providedComSpec 0..*</code>, Generalisierung, <code>+dataElement 1</code>, <code>+initValue 0..1</code>) entfernt.</li>\n<li>Klasse <code>PersistencyDataElement</code>: Stereotyp bzw. Supertyp <code>PersistencyInterfaceElement</code> ergänzt; Attribut <code>updateStrategy: PersistencyElementLevelUpdateStrategyEnum [0..1]</code> entfernt.</li>\n</ul>"}, {"from": "FIG-2c70aa6302af29a4", "to": "FIG-1a2732c4ad1e1a3d", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Diagrammlayout von vertikaler auf horizontale Anordnung umgestellt: <code>RPortComSpec</code> und <code>AbstractRequiredPortPrototype</code> oben nebeneinander, <code>PersistencyDataRequiredComSpec</code> links unten, <code>ValueSpecification</code> und <code>PersistencyDataElement</code> rechts unten übereinander.</li>\n<li>Komposition <code>+requiredComSpec 0..*</code> verläuft horizontal von <code>AbstractRequiredPortPrototype</code> nach links zu <code>RPortComSpec</code>.</li>\n<li>Komposition <code>+initValue 0..1</code> und Assoziation <code>+dataElement 1</code> verlaufen horizontal von <code>PersistencyDataRequiredComSpec</code> nach rechts zu <code>ValueSpecification</code> bzw. <code>PersistencyDataElement</code>.</li>\n</ul>"}, {"from": "FIG-1a2732c4ad1e1a3d", "to": "FIG-ca0ed6ec0cbf9114", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Kardinalität der gerichteten Assoziation <code>+dataElement</code> von <code>PersistencyDataRequiredComSpec</code> auf <code>PersistencyDataElement</code> von <code>1</code> auf <code>0..1</code> geändert.</li>\n</ul>"}, {"from": "FIG-ca0ed6ec0cbf9114", "to": "FIG-fecb9345a1146cca", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Komposition <code>AbstractRequiredPortPrototype</code> zu <code>RPortComSpec</code> (<code>+requiredComSpec 0..*</code>): Stereotyp <code>«atpSplitable»</code> hinzugefügt.</li>\n<li>Umstrukturierung des Layouts von zweizeilig auf einzeilige horizontale Anordnung.</li>\n</ul>"}, {"from": "FIG-fecb9345a1146cca", "to": "FIG-90c21340cfd404d8", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Klasse <code>AbstractPersistencyRequireComSpec</code> als Zwischenklasse eingefügt: erbt von <code>RPortComSpec</code> und ist Basisklasse von <code>PersistencyDataRequiredComSpec</code>.</li>\n<li>Attribut <code>+ accessMode: PersistencyAccessEnum [0..1]</code> in <code>AbstractPersistencyRequireComSpec</code> hinzugefügt.</li>\n<li>Enumeration <code>«enumeration» PersistencyAccessEnum</code> mit den Literalen <code>read</code>, <code>write</code> und <code>readWrite</code> hinzugefügt.</li>\n</ul>"}, {"from": "FIG-90c21340cfd404d8", "to": "FIG-381a8f592cbd83e0", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Enumeration <code>PersistencyAccessEnum</code>: Literal <code>writeOnlyOnce</code> ergänzt.</li>\n<li>Assoziation <code>PersistencyDataRequiredComSpec</code> zu <code>PersistencyDataElement</code> (<code>+dataElement 0..1</code>): Stereotyp <code>«atpIdentityContributor»</code> hinzugefügt.</li>\n</ul>"}]};
